args.sparql:
SELECT ?wife ?birthPlace ?wifeLabel ?birthPlaceLabel WHERE {
  dbr:Thomas_Forsthoefel dbo:spouse ?wife .
  ?wife dbo:birthPlace ?birthPlace .
  OPTIONAL { ?wife rdfs:label ?wifeLabel . FILTER(lang(?wifeLabel) = "en") }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel) = "en") }
}

